const handleScrollState = () => {
	document.body.classList.toggle(
		'scrolled',
		window.scrollY > 50
	);
};

handleScrollState();

window.addEventListener(
	'scroll',
	handleScrollState,
	{ passive: true }
);

document.addEventListener('click', (event) => {
  const link = event.target.closest('a[href="#open-chat"]');

  if (!link) return;

  event.preventDefault();

  const chat = document.querySelector('#ShopifyChat');

  if (!chat || chat.getAttribute('is-open') === 'true') return;

  const button = chat.shadowRoot?.querySelector(
    'button.chat-toggle, .chat-app > button'
  );

  button?.click();
});